final notifications = FlutterLocalNotificationsPlugin();
String jalaliDate(DateTime d){final j=Gregorian.fromDateTime(d).toJalali();return '${j.year}/${j.month.toString().padLeft(2,'0')}/${j.day.toString().padLeft(2,'0')}';}
String clock(DateTime d)=>'${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';
String newId()=>DateTime.now().microsecondsSinceEpoch.toString();
Future<DateTime?> showArvinDatePicker({required BuildContext context,required DateTime firstDate,required DateTime lastDate,required DateTime initialDate})async{final p=await showJalaliDatePicker(context,initialDate:Gregorian.fromDateTime(initialDate).toJalali(),firstDate:Gregorian.fromDateTime(firstDate).toJalali(),lastDate:Gregorian.fromDateTime(lastDate).toJalali());if(p==null)return null;final g=p.toGregorian();return DateTime(g.year,g.month,g.day);}

class FollowUp{String id,text;DateTime at;DateTime? reminderAt;FollowUp({required this.id,required this.text,required this.at,this.reminderAt});Map<String,dynamic> toJson()=>{'id':id,'text':text,'at':at.toIso8601String(),'reminderAt':reminderAt?.toIso8601String()};factory FollowUp.fromJson(Map<String,dynamic> j)=>FollowUp(id:j['id']??newId(),text:j['text']??'',at:DateTime.parse(j['at']),reminderAt:j['reminderAt']==null?null:DateTime.tryParse(j['reminderAt']));}
class ArvinItem{String id,title,description,category;DateTime date;DateTime? reminderAt;bool task,archived,trashed,tracking;List<String> tags,checklist;List<bool> checked;List<FollowUp> followUps;ArvinItem({required this.id,required this.title,required this.description,required this.category,required this.date,required this.task,required this.tags,required this.checklist,required this.checked,required this.followUps,this.reminderAt,this.archived=false,this.trashed=false,this.tracking=false});Map<String,dynamic> toJson()=>{'id':id,'title':title,'description':description,'category':category,'date':date.toIso8601String(),'reminderAt':reminderAt?.toIso8601String(),'task':task,'archived':archived,'trashed':trashed,'tracking':tracking,'tags':tags,'checklist':checklist,'checked':checked,'followUps':followUps.map((e)=>e.toJson()).toList()};factory ArvinItem.fromJson(Map<String,dynamic> j){final c=List<String>.from(j['checklist']??[]);final ch=List<bool>.from(j['checked']??[]);while(ch.length<c.length){ch.add(false);}return ArvinItem(id:j['id']??newId(),title:j['title']??'',description:j['description']??'',category:j['category']??'عمومی',date:DateTime.parse(j['date']),reminderAt:j['reminderAt']==null?null:DateTime.tryParse(j['reminderAt']),task:j['task']??false,archived:j['archived']??false,trashed:j['trashed']??false,tracking:j['tracking']??false,tags:List<String>.from(j['tags']??[]),checklist:c,checked:ch,followUps:(j['followUps'] as List? ??[]).map((e)=>FollowUp.fromJson(Map<String,dynamic>.from(e))).toList());}}

Future<void> initNotifications()async{tz.initializeTimeZones();tz.setLocalLocation(tz.getLocation('Asia/Tehran'));await notifications.initialize(const InitializationSettings(android:AndroidInitializationSettings('@mipmap/ic_launcher'),iOS:DarwinInitializationSettings()));await notifications.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()?.requestNotificationsPermission();}
Future<void> scheduleReminder({required int id,required String title,required String body,required DateTime when})async{if(!when.isAfter(DateTime.now()))return;const a=AndroidNotificationDetails('arvin_reminders','یادآوری‌های آروین',channelDescription:'یادآوری کارها و پیگیری‌های آروین',importance:Importance.max,priority:Priority.high);await notifications.zonedSchedule(id,title,body,tz.TZDateTime.from(when,tz.local),const NotificationDetails(android:a,iOS:DarwinNotificationDetails()),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle);}
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();await initNotifications();runApp(const ArvinApp());}

class ArvinApp extends StatefulWidget{const ArvinApp({super.key});@override State<ArvinApp> createState()=>_ArvinAppState();}
class _ArvinAppState extends State<ArvinApp>{bool dark=false;@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'آروین',theme:ThemeData(useMaterial3:true,fontFamily:'Vazirmatn',colorSchemeSeed:Colors.indigo),darkTheme:ThemeData(useMaterial3:true,fontFamily:'Vazirmatn',colorSchemeSeed:Colors.indigo,brightness:Brightness.dark),themeMode:dark?ThemeMode.dark:ThemeMode.light,home:Directionality(textDirection:TextDirection.rtl,child:Home(onToggleTheme:()=>setState(()=>dark=!dark))));}}

class Home extends StatefulWidget{final VoidCallback onToggleTheme;const Home({super.key,required this.onToggleTheme});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{List<ArvinItem> items=[];List<String> categories=['عمومی'];String filter='همه',categoryFilter='همه',sort='آخرین وارده';bool reverse=false,loading=true;
@override void initState(){super.initState();load();}
Future<void> load()async{final p=await SharedPreferences.getInstance();final raw=p.getString('arvin_items');if(raw!=null){items=(jsonDecode(raw)as List).map((e)=>ArvinItem.fromJson(Map<String,dynamic>.from(e))).toList();}categories=p.getStringList('arvin_categories')??['عمومی'];if(mounted)setState(()=>loading=false);}
Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString('arvin_items',jsonEncode(items.map((e)=>e.toJson()).toList()));await p.setStringList('arvin_categories',categories);}
bool sameDay(DateTime a,DateTime b)=>a.year==b.year&&a.month==b.month&&a.day==b.day;
List<ArvinItem> get shown{var r=items.where((x)=>!x.trashed).where((x){switch(filter){case'یادداشت‌ها':return !x.task&&!x.archived;case'کارها':return x.task&&!x.archived;case'امروز':return sameDay(x.date,DateTime.now())&&!x.archived;case'آینده':return x.date.isAfter(DateTime.now())&&!x.archived;case'عقب‌افتاده':return x.date.isBefore(DateTime.now())&&!sameDay(x.date,DateTime.now())&&!x.archived;case'بایگانی':return x.archived;default:return !x.archived;}}).where((x)=>categoryFilter=='همه'||x.category==categoryFilter).toList();r.sort((a,b){int z;if(sort=='عنوان'){z=a.title.compareTo(b.title);}else if(sort=='تاریخ'){z=a.date.compareTo(b.date);}else{final aa=a.followUps.isEmpty?a.date:a.followUps.last.at;final bb=b.followUps.isEmpty?b.date:b.followUps.last.at;z=aa.compareTo(bb);}return reverse?z:-z;});return r;}
Future<void> addOrEdit({ArvinItem? existing,required bool task})async{await showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>EntryEditor(task:task,categories:categories,existing:existing,onSave:(data)async{setState((){if(existing==null){items.add(data);}else{existing..title=data.title..description=data.description..category=data.category..date=data.date..reminderAt=data.reminderAt..tags=data.tags..checklist=data.checklist..checked=data.checked;}});if(data.reminderAt!=null){await scheduleReminder(id:('item-${data.id}').hashCode,title:'یادآوری آروین: ${data.title}',body:data.description.isEmpty?'زمان یادآوری فرا رسیده است.':data.description,when:data.reminderAt!);}await save();}));}
void openItem(ArvinItem item){Navigator.push(context,MaterialPageRoute(builder:(_)=>DetailsPage(item:item,onEdit:()=>addOrEdit(existing:item,task:item.task),onFollow:()=>addFollowUp(item),onEditFollow:(f)=>editFollowUp(item,f),onDeleteFollow:(f)=>deleteFollowUp(item,f),onChange:(){setState((){});save();})));}
