Future<void> editFollowUp(ArvinItem item,FollowUp f)async{final tc=TextEditingController(text:f.text);DateTime at=f.at;DateTime? reminder=f.reminderAt;await showDialog<void>(context:context,builder:(_)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:const Text('ویرایش پیگیری'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:tc,maxLines:4,decoration:const InputDecoration(labelText:'شرح پیگیری')),ListTile(leading:const Icon(Icons.event),title:Text('تاریخ ثبت: ${jalaliDate(at)} • ${clock(at)}'),onTap:()async{final d=await showArvinDatePicker(context:c,firstDate:DateTime(2020),lastDate:DateTime(2100),initialDate:at);if(d==null)return;final t=await showTimePicker(context:c,initialTime:TimeOfDay.fromDateTime(at));if(t!=null)setD(()=>at=DateTime(d.year,d.month,d.day,t.hour,t.minute));}),ListTile(leading:const Icon(Icons.notifications_active_outlined),title:Text(reminder==null?'یادآوری ندارد':'یادآوری: ${jalaliDate(reminder!)} • ${clock(reminder!)}'),trailing:reminder==null?null:IconButton(icon:const Icon(Icons.clear),onPressed:()=>setD(()=>reminder=null)),onTap:()async{final d=await showArvinDatePicker(context:c,firstDate:DateTime.now(),lastDate:DateTime(2100),initialDate:reminder??DateTime.now());if(d==null)return;final t=await showTimePicker(context:c,initialTime:TimeOfDay.fromDateTime(reminder??DateTime.now()));if(t!=null)setD(()=>reminder=DateTime(d.year,d.month,d.day,t.hour,t.minute));})]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('لغو')),FilledButton(onPressed:()async{f.text=tc.text.trim();f.at=at;f.reminderAt=reminder;await save();setState((){});if(reminder!=null)await scheduleReminder(id:('follow-${f.id}').hashCode,title:'یادآوری پیگیری: ${item.title}',body:f.text,when:reminder!);if(mounted)Navigator.pop(c);},child:const Text('ذخیره'))]})));}
