void sortDialog(){showModalBottomSheet(context:context,builder:(_)=>Column(mainAxisSize:MainAxisSize.min,children:[for(final v in['آخرین وارده','تاریخ','عنوان'])ListTile(title:Text(v),trailing:Icon(reverse?Icons.arrow_upward:Icons.arrow_downward),onTap:(){setState((){if(sort==v){reverse=!reverse;}else{sort=v;reverse=false;}});Navigator.pop(context);})]));}
