class _EntryEditorState extends State<EntryEditor>{late TextEditingController title,desc,tags,checklist;late String category;late DateTime date;DateTime? reminder;@override void initState(){super.initState();final x=widget.existing;title=TextEditingController(text:x?.title??'');desc=TextEditingController(text:x?.description??'');tags=TextEditingController(text:x?.tags.join(', ')??'');checklist=TextEditingController(text:x?.checklist.join('\n')??'');category=x?.category??widget.categories.first;date=x?.date??DateTime.now();reminder=x?.reminderAt;}@override void dispose(){title.dispose();desc.dispose();tags.dispose();checklist.dispose();super.dispose();}Future<void> pickDate()async{final d=await showArvinDatePicker(context:context,firstDate:DateTime(2020),lastDate:DateTime(2100),initialDate:date);if(d==null)return;final t=await showTimePicker(context:context,initialTime:TimeOfDay.fromDateTime(date));if(t!=null)setState(()=>date=DateTime(d.year,d.month,d.day,t.hour,t.minute));}Future<void> pickReminder()async{final d=await showArvinDatePicker(context:context,firstDate:DateTime.now(),lastDate:DateTime(2100),initialDate:reminder??DateTime.now());if(d==null)return;final t=await showTimePicker(context:context,initialTime:TimeOfDay.fromDateTime(reminder??DateTime.now()));if(t!=null)setState(()=>reminder=DateTime(d.year,d.month,d.day,t.hour,t.minute));}Future<void> submit()async{final t=title.text.trim();if(t.isEmpty)return;final checks=checklist.text.split('\n').map((e)=>e.trim()).where((e)=>e.isNotEmpty).toList();final old=widget.existing;final data=ArvinItem(id:old?.id??newId(),title:t,description:desc.text.trim(),category:category,date:date,reminderAt:reminder,task:widget.task,tags:tags.text.split(',').map((e)=>e.trim()).where((e)=>e.isNotEmpty).toList(),checklist:checks,checked:List<bool>.generate(checks.length,(i)=>i<(old?.checked.length??0)?old!.checked[i]:false),followUps:List<FollowUp>.from(old?.followUps??[]),archived:old?.archived??false,trashed:old?.trashed??fals